/// Comprehensive form evaluation feedback generated by the AI Form Coach.
class FormFeedback {
  final int score; // 0 to 100
  final double confidence; // 0.0 to 1.0
  final List<String> warnings;
  final List<String> corrections;
  final List<String> positiveFeedback;

  /// False when the joints this exercise needs were not visible, so the frame
  /// could not be judged. Such frames carry no score.
  final bool bodyVisible;

  FormFeedback({
    required this.score,
    required this.warnings,
    required this.corrections,
    this.confidence = 1.0,
    this.positiveFeedback = const [],
    this.bodyVisible = true,
  });

  bool get isGoodForm => score >= 80;
  bool get hasWarnings => warnings.isNotEmpty;
  int get confidencePercentage => (confidence * 100).round().clamp(0, 100);

  String get gradeLabel {
    if (score >= 90) return 'Elite Form';
    if (score >= 80) return 'Good Form';
    if (score >= 65) return 'Fair - Needs Polish';
    return 'Action Needed';
  }

  factory FormFeedback.fromJson(Map<String, dynamic> json) {
    return FormFeedback(
      score: (json['score'] as num? ?? 100).toInt(),
      confidence: (json['confidence'] as num? ?? 1.0).toDouble(),
      warnings: (json['warnings'] as List? ?? [])
          .map((e) => e.toString())
          .toList(),
      corrections: (json['corrections'] as List? ?? [])
          .map((e) => e.toString())
          .toList(),
      positiveFeedback:
          (json['positiveFeedback'] as List? ??
                  json['positive_feedback'] as List? ??
                  [])
              .map((e) => e.toString())
              .toList(),
      bodyVisible: json['bodyVisible'] as bool? ?? true,
    );
  }

  Map<String, dynamic> toJson() => {
    'score': score,
    'confidence': confidence,
    'warnings': warnings,
    'corrections': corrections,
    'positiveFeedback': positiveFeedback,
    'bodyVisible': bodyVisible,
  };
}
